const rows = $input.all().map((item) => item.json);
if (rows.length === 0) throw new Error('Die Match-CSV ist leer.');

const norm = (v) => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '');
const keys = Object.keys(rows[0]);
const findKey = (...aliases) => keys.find((k) => aliases.some((a) => norm(k) === norm(a)));

const dateKey = findKey('Datum', 'Date');
const homeKey = findKey('Heimteam', 'HomeTeam', 'Home Team');
const awayKey = findKey('Auswärtsteam', 'Auswaertsteam', 'AwayTeam', 'Away Team');
const scoreKey = findKey('Tore', 'Score');
const homeGoalsKey = findKey('Home Goals', 'HomeGoals', 'Goals Home', 'FTHG');
const awayGoalsKey = findKey('Away Goals', 'AwayGoals', 'Goals Away', 'FTAG');
const homeXgKey = findKey('Home xG', 'HomeXG', 'xG Home');
const awayXgKey = findKey('Away xG', 'AwayXG', 'xG Away');

const missing = [];
if (!dateKey) missing.push('Datum/Date');
if (!homeKey) missing.push('Heimteam/HomeTeam');
if (!awayKey) missing.push('Auswärtsteam/AwayTeam');
if (!scoreKey && !(homeGoalsKey && awayGoalsKey)) missing.push('Tore oder Home/Away Goals');
if (!homeXgKey) missing.push('Home xG');
if (!awayXgKey) missing.push('Away xG');
if (missing.length) throw new Error(`Falsche Match-CSV: Pflichtspalten fehlen: ${missing.join(', ')}`);

if (rows.length < 300) throw new Error(`Die Match-CSV enthält nur ${rows.length} Zeilen. Erwartet wird der vollständige Bundesliga-Datensatz 2025/26 (306 Spiele), keine Stichprobe.`);

const clubs = new Set();
for (const row of rows) { clubs.add(String(row[homeKey] ?? '').trim()); clubs.add(String(row[awayKey] ?? '').trim()); }
clubs.delete('');
if (clubs.size !== 18) throw new Error(`Die Match-CSV deckt ${clubs.size} Vereine ab; erwartet werden alle 18 Bundesliga-Vereine 2025/26.`);

const importedAt = new Date().toISOString();
const records = rows.map((row, index) => ({ dataset: 'matches', rowNumber: index + 1, sourceFile: 'bundesliga_2025_26_match_analytics.csv', importedAt, payload: JSON.stringify(row) }));
return [{ json: { dataset: 'matches', rowCount: rows.length, clubCount: clubs.size, importedAt, records } }];

const rows = $input.all().map((item) => item.json);
if (rows.length === 0) throw new Error('Die Player-CSV ist leer.');

const norm = (v) => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '');
const keys = Object.keys(rows[0]);
const findKey = (...aliases) => keys.find((k) => aliases.some((a) => norm(k) === norm(a)));
const playerKey = findKey('Player', 'Name');
const squadKey = findKey('Squad', 'Club', 'Team');
const positionKey = findKey('Position', 'Pos');
const ageKey = findKey('Age');
const minutesKey = findKey('Minutes', 'Min', 'Playing Time Min', 'minutesPlayed');
const missing = [];
if (!playerKey) missing.push('Player');
if (!squadKey) missing.push('Squad');
if (!positionKey) missing.push('Position');
if (!ageKey) missing.push('Age');
if (!minutesKey) missing.push('Minutes');
if (missing.length) throw new Error(`Falsche Player-CSV: Pflichtspalten fehlen: ${missing.join(', ')}`);
if (rows.length < 2000) throw new Error(`Die Player-CSV enthält nur ${rows.length} Zeilen. Erwartet wird der vollständige 2025/26-Top-5-Ligen-Datensatz (~2.433 Spieler), keine Stichprobe.`);
const importedAt = new Date().toISOString();
const records = rows.map((row, index) => ({ dataset: 'players', rowNumber: index + 1, sourceFile: 'players_data-2025_2026-full.csv', importedAt, payload: JSON.stringify(row) }));
return [{ json: { dataset: 'players', rowCount: rows.length, columnCount: keys.length, importedAt, records } }];

const results = $input.all().map((i) => i.json);
const byName = Object.fromEntries(results.map((r) => [r.dataset, r]));
return [{ json: { ok: true, message: 'Originaldaten erfolgreich in n8n Data Table football_scouting_raw importiert.', matches: byName.matches, players: byName.players } }];
